def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 1 or no_water >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif hp <= 2 or no_water >= 1:
        bid = max(DAILY_SALARY * 0.8, avg_prev + 3.0)
    else:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.62, avg_prev + 2.0)
        elif ample_supply:
            bid = DAILY_SALARY * 0.28
        else:
            bid = DAILY_SALARY * 0.42

    if highest_prev >= 100:
        if hp >= 4 and no_water == 0:
            bid = min(bid, DAILY_SALARY * 0.35)
        else:
            bid = max(bid, DAILY_SALARY * 0.78)
    elif highest_prev >= 75:
        if hp >= 5 and no_water == 0 and not tight_supply:
            bid = min(bid, DAILY_SALARY * 0.38)
        else:
            bid = max(bid, DAILY_SALARY * 0.6)
    else:
        bid = max(bid, highest_prev + 1.5 if highest_prev > 0 else bid)

    if desperate_count >= 2:
        bid += 4.0
    elif desperate_count == 0 and ample_supply and hp >= 4:
        bid -= 4.0

    if rich_count >= 1 and highest_prev >= 95 and hp >= 4 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.34)

    if day >= 8:
        if hp <= 3:
            bid = max(bid, DAILY_SALARY * 0.82)
        else:
            bid = max(bid, DAILY_SALARY * 0.5)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', MIN_SUPPLY))
    day = int(day_context.get('day', 0))

    # Identify alive opponents and extract yesterday bids
    alive_opps = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If no one alive, conserve
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Pressure estimate from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Supply-based intensity: higher supply -> can be a bit more aggressive without risking long no-water streaks
    # Convert to a 0..1 factor using safe bounds
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_factor < 0.0:
        supply_factor = 0.0
    if supply_factor > 1.0:
        supply_factor = 1.0

    # Target bidding band exploiting yesterday: opponents who survived bid around 95-103.
    # Undercut slightly to win when they overpay.
    base_target = 0.0

    # If someone previously paid very high, we must respond to avoid being outbid on critical days.
    if highest_prev_bid >= DAILY_SALARY * 0.95:  # ~85.5
        # Healthy: bid just below the top pressure; low HP: bid near top.
        if my_hp > 4.0:
            base_target = highest_prev_bid * 0.92
        else:
            base_target = highest_prev_bid * 0.98
    else:
        # Otherwise, hover around the average pressure, slightly below it.
        if avg_prev_bid > 0.0:
            base_target = avg_prev_bid * 0.93
        else:
            base_target = DAILY_SALARY * (0.50 + 0.20 * supply_factor)

    # Ensure minimum meaningful bid to secure water when supply is scarce.
    scarcity_boost = 0.0
    if supply < 18.0:
        scarcity_boost = 0.10 * DAILY_SALARY

    # If my HP is critical, prioritize survival.
    if my_hp <= 2.0:
        base_target = max(base_target, DAILY_SALARY * 0.85)
    elif my_hp <= 4.0:
        base_target = max(base_target, DAILY_SALARY * 0.65)

    # Slightly increase bids later in episode to avoid falling behind.
    # Episode length is 10; day is 0..9 typically.
    progress = 0.0
    try:
        progress = float(day) / 9.0
    except Exception:
        progress = 0.0
    if progress < 0.0:
        progress = 0.0
    if progress > 1.0:
        progress = 1.0

    base_target = base_target + scarcity_boost + (DAILY_SALARY * 0.05 * progress)

    # Cap by budget and keep within a reasonable range.
    bid = min(my_budget, base_target)

    # Safety clamp: bid should be non-negative.
    if bid < 0.0:
        bid = 0.0

    # If budget is extremely low, bid what we can.
    if my_budget <= 1.0:
        return my_budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0) 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = DAILY_SALARY * 0.7 

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.95 
    elif my_status['hp'] <= 5:
        bid = DAILY_SALARY * 0.85 
    else:
        if highest_prev_bid > DAILY_SALARY * 0.6:
            bid = min(DAILY_SALARY * 0.8, highest_prev_bid + 5.0) 
        else:
            bid = DAILY_SALARY * 0.7 

    days_remaining = EPISODE_DAYS - day_context['day']
    if days_remaining <= 3 and my_status['budget'] > bid:
        bid = max(bid, DAILY_SALARY * 0.8)

    final_bid = min(bid, my_status['budget'])

    return max(1.0, final_bid)
